def build_client_session(api_key: Optional[str]=None, proxies: Optional[
    Dict[str, str]]=None, headers: Optional[Dict[str, str]]=None) ->Tuple[
    SafetyAuthSession, Dict[str, Any]]:
    session = SafetyAuthSession(
        client_id=CLIENT_ID,
        server_metadata_url=OPENID_CONFIG_URL,
        token_endpoint_auth_method='client_secret_post',
        scope='openid profile email',
        timeout=REQUEST_TIMEOUT
    )

    if api_key:
        session.api_key = api_key

    if proxies:
        session.mount('http://', S3PresignedAdapter(**proxies))
        session.mount('https://', S3PresignedAdapter(**proxies))

    if headers:
        session.headers.update(headers)

    return session, {}


def inject_session(func: Callable) ->Callable:
    @wraps(func)
    def wrapper(*args, **kwargs):
        click_ctx = click.get_current_context()
        session, _ = build_client_session()
        try:
            load_auth_session(click_ctx)
        except Exception:
            pass
        kwargs['session'] = session
        return func(*args, **kwargs)
    return wrapper
